
#[cfg(test)]mod freezing80_development_tests {
 use super::*;
 const RAW:&[u8]=include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\驗證紀錄\current\native-E149-freezing80-shock87-inspection\20261024-172131-694095\3933.definition.txt");
 fn catalog(raw:&[u8])->SpriteActionCatalog{SpriteActionCatalog::parse_for_inspection(&[b"11297 0 0\n".as_slice(),raw].concat(),super::super::sprite_actions::ActionLimits::default()).unwrap()}
 fn world()->World{let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w.learned_skills.clear();w.learned_skills.insert(80);w}
 fn packet(w:&World)->Vec<u8>{let a=w.own_actor().unwrap();let mut b=vec![57,18];b.extend(a.id.to_le_bytes());b.extend(a.x.to_le_bytes());b.extend(a.y.to_le_bytes());b.push(3);b.extend(7_u32.to_le_bytes());b.extend(3933_u16.to_le_bytes());b.extend([0,0,0,1,0]);b.extend(0x71234567_u32.to_le_bytes());b.push(32);b}
 fn event(w:&World)->EnteredEvent{let a=w.own_actor().unwrap();EnteredEvent{actor:a.id,sequence:a.action_sequence,action:18,frame:1,event:"Hit".into(),sound:None,prepared_audio:None}}
 fn model()->Effects{let mut e=Effects::default();let mut a=qualify_freezing80(&catalog(RAW)).unwrap().remove(0).2;for f in &mut a.frames{f.events.clear();}e.clips.insert(3933,Clip::new(Arc::new(a)).unwrap());e}
 #[test]fn original_class_zero_keeps_thirtyone_frames_overlap1353_and_no_Hit(){let a=qualify_freezing80(&catalog(RAW)).unwrap().remove(0).2;assert_eq!(a.frames.len(),31);let group=super::super::combat_animation::classify_native_cues(&a.frames[1].events).unwrap().audio.unwrap();assert_eq!(group.candidates(),&[1353]);assert_eq!(group.mode,super::super::combat_animation::NativeAudioMode::AllowOverlappingVoices);let s=String::from_utf8(RAW.to_vec()).unwrap();for(a,b)in[("<1353","[1353"),("104.attr(8)","104.attr(128)"),("0.29:6","0.29:5")]{assert!(s.contains(a));assert!(qualify_freezing80(&catalog(s.replace(a,b).as_bytes())).is_err());}}
 #[test]fn sound_is_initial_and_model_visual_finishes5440ms_without_status_timer(){let clip=Clip::new(Arc::new(qualify_freezing80(&catalog(RAW)).unwrap().remove(0).2)).unwrap();let mut p=clip.start();let mut s=p.advance(0).unwrap();let(mut sounds,mut at)=(vec![],0);while !s.finished{for c in &s.crossed_cues{if c.event==FrameEvent::Effect(1353){sounds.push(at);}}at=p.next_callback_millis().unwrap();s=p.advance(at*1_000_000).unwrap();}assert_eq!(sounds,vec![0]);assert_eq!(at,5440);assert_eq!(s.source_frame,0);let mut p=clip.start();p.advance(0).unwrap();assert_eq!(p.advance(1_000_000_000).unwrap().source_frame,2);assert_eq!(p.next_callback_millis(),Some(1166));}
 #[test]fn only_type_zero_empty_text_and_exact_target_tail_are_admitted(){let mut w=world();let b=packet(&w);assert_eq!(decode(&b).unwrap().unwrap().graphics,3933);let mut wrong=b.clone();wrong[17]=8;assert!(decode(&wrong).unwrap().is_none());for bad in [b[..b.len()-1].to_vec(),{let mut b=b.clone();*b.last_mut().unwrap()=1;b}]{let before=serde_json::to_value(&w).unwrap();assert!(w.accept(&bad).is_err());assert_eq!(serde_json::to_value(&w).unwrap(),before);}}
 #[test]fn wire_origin_stays_frozen_and_presentation_never_invents_damage_or_paralysis(){let mut w=world();w.accept(&packet(&w)).unwrap();let launch=event(&w);let original=w.own_actor().unwrap().clone();let mut e=model();assert!(e.update(&w,[&launch].into_iter(),0).is_empty());assert!(e.active[0].cue.target_origin.is_none());w.actors.get_mut(&original.id).unwrap().x+=9;let before=serde_json::to_value(&w).unwrap();while !e.active[0].finished{let at=e.active[0].playback.next_callback_millis().unwrap();assert!(e.update(&w,std::iter::empty(),at*1_000_000).is_empty());assert!(e.non_audio.is_empty());}assert_eq!(e.active[0].cue.attack.position,[original.x,original.y]);assert_eq!(e.hits,0);assert_eq!(serde_json::to_value(&w).unwrap(),before);let mut restored=model();restored.restore_history(e.history());restored.update(&w,[&launch].into_iter(),6_000_000_000);assert_eq!(restored.started,1);}
 #[test]fn failed_reprepare_retires_once_and_does_not_restart_old_audio(){let mut w=world();w.accept(&packet(&w)).unwrap();let launch=event(&w);let mut e=model();e.update(&w,[&launch].into_iter(),0);let mut restored=Effects::default();restored.restore_history(e.history());restored.error=Some("cancelled original preparation".into());restored.update(&w,std::iter::empty(),166_000_000);assert_eq!(restored.omitted,1);assert!(restored.history().active_sequences().is_empty());restored.update(&w,[&launch].into_iter(),332_000_000);assert_eq!(restored.omitted,1);}
 #[test]
 #[ignore="LITO_SHARED_RESOURCE_ROOT; original3933/1353 at received wire caster, memory fragments only"]
 fn original_bank_draws_one_Screen_layer_and_world_overlap_at_wire_origin(){let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit shared root").into();let cancel=AtomicBool::new(false);let mut w=world();let own=w.own_actor().unwrap().clone();w.accept(&packet(&w)).unwrap();w.actors.get_mut(&own.id).unwrap().x+=3;let launch=event(&w);let authority=(w.hp,w.mp,w.movement_blocks.clone());let mut e=Effects::default();e.prepare(&root,&w,&cancel);assert!(e.error.is_none());e.update(&w,[&launch].into_iter(),0);let view=ViewProjection{anchor_cell:WorldCell{x:i32::from(own.x),y:i32::from(own.y)},anchor_pixel:super::super::world_map::PixelPoint{x:400,y:300}};let mut q=vec![];let(_,audio)=e.draw_to(&mut Target::Fragments(&mut q),view,0);assert_eq!(q.len(),1);assert!(matches!(q[0].mix,Mix::Screen));assert_eq!(q[0].position,view.anchor_cell);assert_eq!(audio.iter().filter(|e|e.actor==0&&e.sound==Some(1353)&&e.prepared_audio.is_some()&&e.event=="ManyAudioOverlap(1353)").count(),1);assert_eq!((w.hp,w.mp,w.movement_blocks.clone()),authority);}
}
